def tr(g): return [list(r) for r in zip(*g)]
def rot(g): return [list(r) for r in zip(*g[::-1])]
def tf(g,i):
    f={'0':lambda x:x,'1':tr,'4':rot,'5':lambda x:rot(rot(x)),'6':lambda x:rot(rot(rot(x))),
       '7':lambda x:[r[::-1] for r in x],'8':lambda x:x[::-1],'9':lambda x:[r[::-1] for r in x][::-1]}
    if i==1: return tr
    return f[str(i)](g)
