def transforms(pts):
    s=set(pts)
    res={}
    res['id']=s
    res['r90']={(c,-r) for r,c in s}
    res['r180']={(-r,-c) for r,c in s}
    res['r270']={(-c,r) for r,c in s}
    res['fh']={(-r,c) for r,c in s}  # flip rows
